descriptor.templateCss:
.fp-rpc { width: 100%; height: 100%; overflow: auto; font-size: 13px; padding: 4px; box-sizing: border-box; }
.fp-rpc .fp-nav { display: flex; gap: 6px; margin-bottom: 8px; flex-wrap: wrap; }
.fp-rpc .fp-row { margin-bottom: 8px; }
.fp-rpc .fp-btn { cursor: pointer; padding: 6px 10px; margin: 0 6px 4px 0; border: 1px solid #305680; background: #fff; border-radius: 4px; }
.fp-rpc .fp-go { background: #305680; color: #fff; }
.fp-rpc .fp-current { font-weight: 700; background: #dbe6f3; }
.fp-rpc .fp-params { display: block; width: 100%; font-family: monospace; box-sizing: border-box; margin-top: 4px; }
.fp-rpc .fp-status { padding: 6px 8px; margin: 8px 0 4px 0; border-radius: 4px; background: #eee; font-weight: 600; }
.fp-rpc .fp-ok { background: #d7f0d7; color: #1b5e20; }
.fp-rpc .fp-err { background: #f8d7d7; color: #b71c1c; }
.fp-rpc .fp-busy { background: #fff3cd; color: #7a5b00; }
.fp-rpc .fp-reply { margin: 0; padding: 6px; background: #f6f6f6; max-height: 320px; overflow: auto; white-space: pre-wrap; word-break: break-all; font-size: 12px; }

descriptor.controllerScript:
self.onInit = function () {
    var ctx = self.ctx;
    var settings = ctx.settings || {};
    var actions = settings.actions || [];
    var nav = settings.nav || [];
    var box = ctx.$container[0];
    var host = box.querySelector('.fp-rpc') || box;
    var rpcOk = ctx.defaultSubscription && ctx.defaultSubscription.rpcEnabled;

    function el(tag, cls, text) {
        var e = document.createElement(tag);
        if (cls) { e.className = cls; }
        if (text !== undefined && text !== null) { e.textContent = text; }
        return e;
    }

    var statusLine = el('div', 'fp-status', rpcOk ? 'พร้อม' : 'ยังไม่ได้เลือกอุปกรณ์เป้าหมาย (Target device is not set)');
    var replyBox = el('pre', 'fp-reply', '');

    function setStatus(kind, text) {
        statusLine.className = 'fp-status fp-' + kind;
        statusLine.textContent = text;
    }

    function showReply(obj) {
        var text;
        try { text = JSON.stringify(obj, null, 2); } catch (e) { text = String(obj); }
        replyBox.textContent = text;
    }

    function dig(obj, path) {
        var cur = obj;
        var parts = String(path).split('.');
        for (var i = 0; i < parts.length; i++) {
            if (cur === null || cur === undefined) { return undefined; }
            cur = cur[parts[i]];
        }
        return cur;
    }

    function send(method, params, label, onReply) {
        if (!rpcOk) { setStatus('err', 'ผิดพลาด: ยังไม่ได้เลือกอุปกรณ์เป้าหมาย'); return; }
        setStatus('busy', 'กำลังส่ง ' + label + ' ...');
        replyBox.textContent = '';
        var obs = ctx.controlApi.sendTwoWayCommand(method, params, 10000);
        obs.subscribe(function (resp) {
            showReply(resp);
            var good = resp !== null && typeof resp === 'object' && resp.ok === true;
            if (good) {
                setStatus('ok', 'OK: ' + label);
            } else {
                var code = (resp && resp.error) ? resp.error : 'ไม่มี ok=true ในคำตอบ';
                setStatus('err', 'ERROR: ' + label + ' (' + code + ')');
            }
            if (onReply) { onReply(resp); }
            ctx.detectChanges();
        }, function (rej) {
            var why = rej && rej.status !== undefined ? (rej.status + ' ' + (rej.statusText || '')) : String(rej);
            showReply({ rpc_failed: why });
            setStatus('err', 'ERROR: ' + label + ' ส่งไม่สำเร็จ ' + why);
            ctx.detectChanges();
        });
    }

    host.innerHTML = '';

    if (nav.length) {
        var bar = el('div', 'fp-nav');
        nav.forEach(function (n) {
            var b = el('button', 'fp-btn fp-navbtn' + (n.current ? ' fp-current' : ''), n.title);
            b.type = 'button';
            b.onclick = function () {
                try { ctx.stateController.openState(n.id, {}, false); } catch (e) { setStatus('err', 'เปลี่ยนหน้าไม่ได้: ' + e); }
            };
            bar.appendChild(b);
        });
        host.appendChild(bar);
    }

    actions.forEach(function (a) {
        var row = el('div', 'fp-row');
        var area = null;
        if (a.edit) {
            area = el('textarea', 'fp-params');
            area.rows = 5;
            area.value = a.params === null || a.params === undefined ? '{}' : JSON.stringify(a.params, null, 2);
            area.spellcheck = false;
        }
        var go = el('button', 'fp-btn fp-go', a.label);
        go.type = 'button';
        go.onclick = function () {
            var params = a.params === null || a.params === undefined ? {} : a.params;
            if (area) {
                try { params = JSON.parse(area.value); } catch (e) {
                    setStatus('err', 'ERROR: params ไม่ใช่ JSON ที่ถูกต้อง (' + e.message + ')');
                    return;
                }
            }
            if (a.confirm) {
                var ask = a.confirm;
                if (params !== null && typeof params === 'object' && params.id !== undefined) {
                    ask += ' (id ' + params.id + ')';
                }
                if (!window.confirm(ask)) { return; }
            }
            send(a.method, params, a.label, null);
        };
        row.appendChild(go);
        if (a.edit && a.load) {
            var ld = el('button', 'fp-btn fp-load', 'โหลดค่าปัจจุบัน');
            ld.type = 'button';
            ld.onclick = function () {
                send(a.load, {}, 'โหลดค่าปัจจุบัน (' + a.load + ')', function (resp) {
                    if (resp === null || typeof resp !== 'object' || resp.ok !== true) { return; }
                    var copy = {};
                    Object.keys(resp).forEach(function (k) { if (k !== 'ok') { copy[k] = resp[k]; } });
                    var val = a.load_path ? dig(copy, a.load_path) : copy;
                    if (val === undefined) {
                        setStatus('err', 'ERROR: ไม่พบ ' + a.load_path + ' ในคำตอบ');
                        return;
                    }
                    if (Array.isArray(a.load_keys) && a.load_keys.length && val !== null && typeof val === 'object' && !Array.isArray(val)) {
                        var kept = {};
                        a.load_keys.forEach(function (k) { if (Object.prototype.hasOwnProperty.call(val, k)) { kept[k] = val[k]; } });
                        val = kept;
                    }
                    area.value = JSON.stringify(val, null, 2);
                });
            };
            row.appendChild(ld);
        }
        if (area) { row.appendChild(area); }
        host.appendChild(row);
    });

    host.appendChild(statusLine);
    host.appendChild(replyBox);
};

self.onDestroy = function () {
    try { self.ctx.controlApi.completedCommand(); } catch (e) { }
};
